// Unit-testable mirror of W3C 'process the id member'
export function resolvedId(id: string | undefined, startUrl: URL): string {
  const start = new URL(startUrl.href); start.hash = '';
  if (!id) return start.href;
  let u: URL;
  try { u = new URL(id, startUrl.origin); } catch { return start.href; }
  if (u.origin !== startUrl.origin) return start.href;
  u.hash = '';
  return u.href;
}
