// Chromium (Chrome, Edge, Samsung, Opera) promotes install and fires beforeinstallprompt when:
//  - HTTPS (or localhost / 127.0.0.1)
//  - manifest has name|short_name, icons incl. 192px AND 512px, start_url,
//    display|display_override in fullscreen|standalone|minimal-ui (|window-controls-overlay)
//  - prefer_related_applications absent or false
//  - not already installed; user engagement: interacted with the origin ~30 s (incl. a tap/click)
//  - a service worker with a fetch handler is NO LONGER required (Chrome 108 Android / 112 desktop)
// Any site (even without a manifest): Chrome desktop+Android menu 'Install page as app';
//   Safari macOS 17+ File > Add to Dock; Safari iOS/iPadOS 26 Share > Add to Home Screen (opens as web app by default)
// Android: real WebAPKs only from Chrome on GMS devices and Samsung Internet; other browsers make browser-badged shortcuts.
// iOS 16.4+: Chrome, Edge, Firefox, Orion can also Add to Home Screen (the app still runs on Safari's web-app runtime).
// Firefox 143+ Windows: address-bar 'web app' button pins any site as a taskbar app (no beforeinstallprompt).

// Register at startup (before the UI mounts): the event can fire very early.
interface InstallPrompt extends Event {
  prompt(): Promise<unknown>;
  readonly userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}
const isInstallPrompt = (e: Event): e is InstallPrompt =>
  'prompt' in e && typeof e.prompt === 'function' && 'userChoice' in e;

let offer: InstallPrompt | null = null;
export function watchInstall(setInstallable: (v: boolean) => void) {
  addEventListener('beforeinstallprompt', (e) => {
    if (!isInstallPrompt(e)) return;
    e.preventDefault();          // no mini-infobar; we offer it ourselves
    offer = e;
    setInstallable(true);
  });
  addEventListener('appinstalled', () => { offer = null; setInstallable(false); });
}
/** Call directly from the click handler (needs user activation). */
export async function install(setInstallable: (v: boolean) => void): Promise<boolean> {
  const o = offer;
  if (!o) return false;
  offer = null;                   // each event can prompt() once
  setInstallable(false);
  await o.prompt();
  return (await o.userChoice).outcome === 'accepted';
}

export function maybeSuggestInstall(s: { onboarded: boolean; standalone: boolean; hintShown: boolean },
                                    markShown: () => void, toast: (t: { title: string; body: string; action: string; onAction: () => void }) => void,
                                    openInstallHelp: () => void) {
  // after the user got value (onboarding done / returning user), never inside the installed app,
  // phones/tablets only (desktop already has the omnibox install icon), once per device.
  if (!s.onboarded || s.standalone || s.hintShown || !matchMedia('(pointer: coarse)').matches) return;
  markShown();                    // persist BEFORE showing, so a reload can't repeat it
  toast({ title: 'Install the app', body: 'Full screen, home-screen icon, notifications.', action: 'How', onAction: openInstallHelp });
}
