const APP_MODES = '(display-mode: standalone), (display-mode: minimal-ui), (display-mode: window-controls-overlay)';
export const isInstalledLaunch = (): boolean =>
  matchMedia(APP_MODES).matches ||
  ('standalone' in navigator && navigator.standalone === true);   // iOS/iPadOS home-screen app

export function watchDisplayMode(cb: (installed: boolean) => void): () => void {
  const mq = matchMedia(APP_MODES);
  const h = () => cb(isInstalledLaunch());
  mq.addEventListener('change', h);
  return () => mq.removeEventListener('change', h);
}

export function setBadge(n: number): void {
  if (!('setAppBadge' in navigator)) return;                 // Firefox, Android Chrome
  const p = n > 0 ? navigator.setAppBadge(n) : navigator.clearAppBadge();
  p.catch(() => { /* not installed / no permission: expected, not an error */ });
}
// in the service worker (e.g. on push): self.navigator.setAppBadge(count)
// setAppBadge() with no argument = plain dot; setAppBadge(0) = clear

export async function setTabBadge(count: number, baseHref: string, baseTitle: string) {
  document.title = count ? `(${count > 9 ? '9+' : count}) ${baseTitle}` : baseTitle;
  const img = new Image(); img.src = baseHref; await img.decode().catch(() => undefined);
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d'); if (!g) return;
  g.drawImage(img, 0, 0, 64, 64);
  if (count) { g.fillStyle = '#e5484d'; g.beginPath(); g.arc(46, 18, 16, 0, Math.PI * 2); g.fill(); }
  const link = document.querySelector<HTMLLinkElement>('link[rel="icon"][type="image/svg+xml"], link[rel="icon"]');
  if (link) link.href = count ? c.toDataURL('image/png') : baseHref;
}

