// sw.ts
declare const self: ServiceWorkerGlobalScope;
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'POST' || !url.pathname.endsWith('/share-target')) return;
  event.respondWith((async () => {
    const form = await event.request.formData();                 // untrusted: validate before use
    const cache = await caches.open('share-inbox');
    await cache.put('text', new Response(JSON.stringify({ title: form.get('title'), text: form.get('text'), url: form.get('url') })));
    for (const [i, f] of form.getAll('files').entries()) if (f instanceof File) await cache.put(`file-${i}`, new Response(f));
    return Response.redirect(new URL('./?shared=1', self.registration.scope).href, 303);
  })());
});

